import{_ as e,c as t,o as n,V as o,an as a,ao as s}from"./chunks/framework.GYYi-SO7.js";const _=JSON.parse('{"title":"Understanding knowledge","description":"","frontmatter":{},"headers":[],"relativePath":"guides/understanding.md","filePath":"guides/understanding.md"}'),i={name:"guides/understanding.md"},r=o('<h1 id="understanding-knowledge" tabindex="-1">Understanding knowledge <a class="header-anchor" href="#understanding-knowledge" aria-label="Permalink to &quot;Understanding knowledge&quot;">​</a></h1><p>AI is becoming essential to our line of work increasingly capable, but also increasingly expensive. The goal of <strong>knowledge</strong> is to give Kalisio developers an AI assistant that is both context-aware and token-efficient, regardless of which coding agent they use.</p><h2 id="why-not-an-existing-solution" tabindex="-1">Why not an existing solution <a class="header-anchor" href="#why-not-an-existing-solution" aria-label="Permalink to &quot;Why not an existing solution&quot;">​</a></h2><p>Several open-source projects already exist to index code and reduce token usage by improving context, such as <a href="https://github.com/zilliztech/claude-context" target="_blank" rel="noreferrer">claude-context</a>. But none of them fit our needs:</p><p><img src="'+a+'" alt="guide why-not"></p><ul><li><strong>Paid dependency</strong> : solutions like claude-context require an OpenAI API key for embeddings, which goes against our open-source philosophy.</li><li><strong>Too agent-specific</strong> : most are built around a single coding agent. The field moves fast enough that today&#39;s dominant tool may not exist tomorrow; we don&#39;t want to lock ourselves in.</li><li><strong>Too generic</strong> : they treat all code the same. We want chunking and handlers tuned to our actual stack, <code>.vue</code>, <code>.js</code>, <code>.json</code>.</li></ul><h2 id="what-knowledge-provides" tabindex="-1">What knowledge provides <a class="header-anchor" href="#what-knowledge-provides" aria-label="Permalink to &quot;What knowledge provides&quot;">​</a></h2><p>knowledge gives every coding agent the same structured context, through a ready-to-use <a href="./agent-config/claude-code.html">configuration per agent</a> and three complementary tools:</p><p><img src="'+s+'" alt="guide provides"></p><ul><li><strong><a href="./semantic-search.html">Semantic code search</a></strong> : the Kalisio codebase is chunked and embedded into <a href="https://qdrant.tech/" target="_blank" rel="noreferrer">Qdrant</a>.</li><li><strong><a href="./git-intelligence.html">Git intelligence</a></strong> : commit history is parsed into hotspot scores, co-change patterns &amp; bus-factor risk.</li><li><strong><a href="./dependency-graph.html">Dependency graph</a></strong> : static AST analysis maps every import to know what depends on what.</li></ul>',10),d=[r];function l(c,g,h,u,p,m){return n(),t("div",null,d)}const k=e(i,[["render",l]]);export{_ as __pageData,k as default};
